//! Test transport only: real bridge queue/response decoding, no real Chrome IO.
//! The reply is generated by executing the current production page function.
use std::{future::Future, sync::OnceLock, time::Duration};

use serde_json::{Value, json};
use synapse_browsers::BrowserKindId;

use super::super::{BRIDGE_PROTOCOL_VERSION, NativeMessageRequest, NativeRegisterRequest, bridge};

static SERIAL: OnceLock<tokio::sync::Mutex<()>> = OnceLock::new();

struct Host {
    id: String,
    previous: Option<String>,
    kind: BrowserKindId,
}

impl Host {
    fn install() -> anyhow::Result<Self> {
        let kind = BrowserKindId::new("chrome").map_err(anyhow::Error::msg)?;
        let previous = bridge()
            .inner
            .lock()
            .map_err(|_| anyhow::anyhow!("bridge lock"))?
            .active_hosts
            .active(&kind)
            .map(str::to_owned);
        let registered = bridge()
            .register(
                NativeRegisterRequest {
                    origin: "chrome-extension://leoocgnkjnplbfdbklajepahofecgfbk/".to_owned(),
                    pid: 0,
                    parent_window: None,
                    bridge_protocol_version: BRIDGE_PROTOCOL_VERSION,
                    transport: None,
                },
                kind.clone(),
            )
            .map_err(anyhow::Error::msg)?;
        let host = Self {
            id: registered.host_id,
            previous,
            kind,
        };
        bridge()
            .post_message(NativeMessageRequest {
                host_id: host.id.clone(),
                message: json!({"type":"hello", "popupRiskSuppression":{
                    "ok":true, "management_available":true, "status":"clear",
                    "remaining_hazard_count":0, "failure_count":0
                }}),
            })
            .map_err(anyhow::Error::msg)?;
        Ok(host)
    }
}

impl Drop for Host {
    fn drop(&mut self) {
        if let Ok(mut inner) = bridge().inner.lock() {
            inner.active_hosts.clear_host(&self.id);
            inner.hosts.remove(&self.id);
            inner.commands.retain(|queued| queued.host_id != self.id);
            inner
                .pending
                .retain(|_, pending| pending.host_id != self.id);
            if let Some(previous) = &self.previous {
                inner.active_hosts.set_active(self.kind.clone(), previous);
            }
        }
    }
}

pub(crate) async fn with_reply<T>(
    kind: &str,
    reply: Value,
    operation: impl Future<Output = T>,
) -> anyhow::Result<T> {
    let _serial = SERIAL
        .get_or_init(|| tokio::sync::Mutex::new(()))
        .lock()
        .await;
    let host = Host::install()?;
    let answer = async {
        let command = bridge()
            .next_command(&host.id, Duration::from_secs(3))
            .await
            .map_err(anyhow::Error::msg)?
            .ok_or_else(|| anyhow::anyhow!("handler never queued {kind}"))?;
        anyhow::ensure!(command.kind == kind, "unexpected command {}", command.kind);
        bridge()
            .post_message(NativeMessageRequest {
                host_id: host.id.clone(),
                message: json!({"type":"response", "id":command.id, "ok":true, "result":reply}),
            })
            .map_err(anyhow::Error::msg)
    };
    let (result, delivered) = tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(operation, answer)
    })
    .await?;
    delivered?;
    Ok(result)
}
